import pandas as pd

def clean(df):
    df = df.copy()
    df = df.drop_duplicates()

    if 'Category' in df.columns:
        df['Category'] = df['Category'].astype('string').str.strip().str.title()

    if 'Region' in df.columns:
        r = df['Region'].astype('string').str.strip().str.title()
        r = r.replace({'Suoth': 'South', 'Eats': 'East'})
        df['Region'] = r

    if 'Date' in df.columns:
        df['Date'] = pd.to_datetime(df['Date'], errors='coerce')

    for c in ['Quantity', 'Price', 'Revenue']:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors='coerce')

    if {'Quantity', 'Price', 'Revenue'}.issubset(df.columns):
        df['Revenue'] = df['Quantity'] * df['Price']

    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['Date', 'Revenue'])
    d['month'] = d['Date'].dt.strftime('%Y-%m')
    out = d.groupby('month', dropna=True)['Revenue'].sum()
    return {str(k): float(v) for k, v in out.items()}
